        descricao: 'Esta técnica é realizada reunindo energia, formando um "túnel" vagamente em forma de diamante com as mãos, mantendo os dedos de cada mão juntos, sobrepondo o dedo indicador de uma mão com o mindinho da outra e sobrepondo os polegares. O objeto em foco é ampliado e visualizado dentro desse diamante, então o usuário grita " Kikōhō!" enquanto libera o grande raio amarelo das mãos. Além de ser capaz de matar o alvo, o Tri-Beam também pode matar o usuário facilmente, drenando sua energia vital. O ataque tende a lançar um brilho laranja intenso em todo o ambiente ao seu redor. [Dano e Ki Variáveis]\nEfeitos:\n➢ Ao declarar o uso desta técnica especial, o usuário de qualquer ponto do “grid” pode se concentrar em ampliar a imagem dentro do diamante formado com sua mão, para atingir somente o alvo. Para cada 6,0m de distância entre o usuário e o alvo, o mesmo paga 01 PK na utilização da técnica. Sendo considerado o ataque considerado alcance do rótulo em “Rastro”. Além disso, o Kikōhō é considerado por rótulos um dano “Potente” e “Consumidor”.\n➢ Diferente de Técnicas de Ki comuns, essa utiliza dos PV’s para determinar o dano variante. O Kikōhō consome a vida do usuário em troca de poder, assim ao conjurar essa técnica, o dano causado pode ser aumentado conforme os PV’s do usuário, sendo considerado dano bônus adicionado após o dano base, ou seja, não entrando na variação de dano padrão do sistema. A vida utilizada como dano bônus no Kikōhō, não pode ser regenerada ou curada até o final da batalha.\n➢ O Dano Base e o Custo de PK’s do Kikōhō, segue a base do sistema conforme tabela da página 51 do Livro do Jogador. Sendo o Rank máximo que se pode utilizar, aquele ao qual o usuário consegue atingir. Então, por exemplo, se um usuário utilizar a Técnica como Rank D, o Dano Base dela será 26 e o Custo em PK’s de 04. Caso tenha dúvidas, essas seriam as variações possíveis em cada Rank: E: (03-06-12) – 01 PK D: (06-13-26) – 04 PK C: (08-17-34) – 06 PK B: (11-22-44) – 08 PK A: (17-34-68) – 12 PK Z: (32-65-130) – 18 PK',
