        efeito: '- Ofensivamente você pode utilizar ela como se fosse um ataque a distância genérico de qualquer rank até o limite que você consegue dominar, ou seja, se por exemplo você quiser aplicar um dano com o máximo possível que uma técnica Rank A chegaria, você teria que de acordo com a tabela de dano das técnicas usar 26 de Ki para causar 124 de dano, ou 12 de Ki para causar 68.\n- Na forma de suporte, com a telecinese você pode redirecionar uma técnica que você utilizou e errou desde que ela tenha o rótulo de “Projétil”, assim gastando metade do custo de Ki que utilizou para a conjurar, para assim fazer uma nova rolagem de ataque no mesmo alvo, ou contra alguém próximo.\n- Você também pode utilizar a ação especial “Agarrar “a distância, e sem a necessidade de estar próximo, e utilizar Inteligência no acerto do agarrão. Além disso, um personagem agarrado pela telecinese por você, gasta o dobro de Ki em ações de reação, e tem sua ação de movimentação não só negada como também controlada por você, podendo te deslocar uma quantidade de metros igual ao deslocamento do agarrado, mas, somente no turno do agarrante. Caso queira deslocar mais do que isto deve gastar 1 PK para cada 1,5m a mais.',
