        texto: 'É o estágio dos Deuses, os seres supremos do Universo de Dragon Ball. Esse Ki é tão poderoso, que apenas outros usuários de Ki Divino podem o sentir. O usuário banhado por esse Ki atinge um novo tipo de Escala de Poder, onde ele é capaz de negar as desvantagens impostas pela diferença de Escala de um adversário mais poderoso que não tenha acesso a esse Ki. O usuário perde as desvantagens impostas pela diferença, mas, o oponente se ainda tiver uma escala superior, mantém suas vantagens naturais.\n➢ Caso você esteja enfrentando um oponente que também tenha acesso ao Ki Divino, as desvantagens de Escala de Poder voltam a aplicar normalmente, já que ambos estão no mesmo estágio.\n➢ Caso você esteja enfrentando alguém que não tenha acesso a este tipo de Ki, e ainda você seja superior em Escala de Poder, mesmo que por apenas um ponto de diferença, você pode aplicar se quiser a regra de vitória interpretativa.\n➢ Além disso tudo você ganha acesso a um novo Rank de Técnica, que é chamada de “Rank God”, onde nele não há limite de Rótulos Positivos e Ki, no entanto ainda deve ser respeitado os rótulos negativos. Tendo as mesmas características do Rank Z, mas, sem o limite de 12 Rótulos Positivos, podendo ultrapassar isto a vontade, além do Ki também.',
