        efeito: '[Requisito Limitador: Ser Divino “Puro” em Corpo Mortal]\nEfeitos:\n- Sempre antes de concretizar uma Ação em seu Turno de Ação, o usuário pode declarar o uso “máximo” de seu poder, fazendo com que qualquer técnica ofensiva utilizada receba o nome “Black” antes de sua utilização, a deixando mais poderosa por estar banhada em um Ki Puro de um Deus misturado com o Ki de um Corpo Mortal. Ao gastar a quantidade de PK’s equivalente a Escala do Poder do alvo, o dano causado é considerado sempre no mínimo “Médio”, mesmo que tenha tido um acerto menor. Além disso, temporariamente sua técnica adquiri o rótulo “Dano Elemental – Sombrio”, que diferente do padrão, este é ativado quando o usuário consegue aplicar dano completo no alvo, e não superando sua CA pelo dobro do que seria acertar por dano completo.',
