        nome: 'Imortalidade',
        tipo: 'Passiva',
        texto: 'Zamasu tem a capacidade de permanecer inalterado com o passar do tempo, incapaz de morrer e simplesmente viver para sempre. Obtida usando as Super Esferas do Dragão. Devido à sua aparente imortalidade, Zamasu do Futuro é apenas moderadamente imperturbável por qualquer ferimento, não importa quão grave seja. No entanto, ele ainda pode ser derrotado selando-o usando técnicas de selamento. Ele também é suscetível a ser apagado da existência por Zeno. Caso você faça Zamasu chegar a 0 PV’s, ele irá ficar atordoado por uma rodada, e no inicio de sua próxima rodada, recupera todos os seus PV’s ao máximo. Nada é capaz de o matar, ou fazer o mesmo ser reduzido a pó, sendo completamente imortal.\n• Adicional ao Zamasu Fundido: Além disso caso esteja no estágio de Zamasu Fundido, ao chegar a 0 PV’s, seu corpo é gravemente danificado, a metade dele fica em uma gosma roxa e sem vida, e o usuário perde acesso as técnicas que a fusão o concede.',
