        rotulosNegativos: {
          pontos: null,
          nomes: [],
        },
        descricao: 'A Transmissão Instantânea permite que o usuário e qualquer pessoa que esteja em contato físico com ele viajem instantaneamente grandes distâncias (de metros a anos-luz, entre o mundo dos vivos e o Outro Mundo , ou até mesmo viajem para além do tempo) apenas concentrando-se na assinatura de ki de um indivíduo específico e transmitindo ou sentindo a localização desse ser. O usuário pode se rematerializar em qualquer lugar dentro de um curto alcance de seu alvo.',
        efeito: 'Efeitos:\n- O Narrador irá determinar a dificuldade do teste para chegar até onde você quer ir com base no Ki de quem você está procurando localizar, quanto mais distante mais difícil de sentir o Ki, no entanto o teste pode facilitar se o alvo estiver utilizando seu Ki ao máximo para ser localizado.\n- Em combate, pode ser utilizado para se locomover e ficar em qualquer um dos lados do alvo, não gastando sua movimentação e sendo instantâneo. Além disso, pode ser usado como reação para evitar ataques completamente, desde que a técnica não seja guiada e o ponto ao qual você se teletransportou, não esteja na área da técnica, e seja um ponto onde tem Ki para você se localizar.\n- Por fim, pode ser usado ofensivamente, com qualquer técnica sua a transformando em uma “Instant Transmission” , onde você aparece a frente do alvo, e por estar a queima roupa e fazendo uma espécie de efeito surpresa forçado, o alvo não tem direito a reação, mas, você ainda deve o acertar. Você só pode fazer isso uma vez por alvo, durante o combate, afinal, após isso fica esse movimento fica previsível.\nDesvantagens:\n- É uma técnica que gasta muito Ki, então sempre que utilizar ela mais de uma vez na mesma rodada seja em ação ou reação, o custo dela acumula com o anterior, ou seja, se você utilizou uma vez durante o turno de reação com 10 de Ki para esquivar, utilizar novamente irá custar 20 de Ki, e assim sucessivamente, apenas resetando o custo em um novo turno de ação ou reação.',
        pagina: 38,
