        descricao: 'Quando as esperanças e energias de todos são reunidas como uma Genki-Dama , o usuário então absorve o poder em seu corpo — fazendo com que uma Espada de Luz se manifeste e se torne muito maior e mais poderosa com seu ki incorporado, criando uma rápida mistura de partículas de ki azuis e douradas antes de se tornar um branco brilhante. Apenas aqueles com coração puro conseguem invocar e controlar essa energia sem sofrer graves consequências — um coração impuro pode resultar na explosão da técnica contra o próprio usuário. Diferente da Genki-Dama comum, essa não precisa de preparação, os seres vivos voluntariamente doam sua energia por ter fé e esperança, e se fundindo ao corpo do usuário ele consegue manifestar a “Genki-Sword of Hope”.',
        efeito: '[Ação] [00 KI]\nEfeito: O Narrador rola 1d20 e multiplica o resultado pela Escala de Poder do planeta para determinar o dano inicial da Genki-Sword, caso seja uma Genki-Sword “Universal” onde outros planetas enviam sua energia, essa rolagem é feita para cada planeta. Outros personagens podem usar suas ações para doar Ki, aumentando o dano final na proporção de 1 ponto de Ki = +1 de dano.\nAdicionalmente:\n- Se Diferente da Genki-Dama comum, ela segue as regras normais de ataque para técnicas. Se o alvo for interpretativamente maligno, a Genki-Sword causa dano crítico garantido ao acertar.\n- Diferente da Genki-Dama comum que é em área, a Genki-Sword é em Alvo Único e no Alcance de Toque. Além disso, ela não é um golpe único como a Genki-Dama original, ela pode ser utilizada como se estivesse utilizando um Rótulo de “Técnica Básica”, no entanto, também diferente da original, o dano dela segue as regras de dano escalonado. Você pode utilizar a Genki-Sword para aplicar golpes um número de vezes igual a sua Escala de Poder Total.\n- A Genki-Sword é tão poderosa, que é capaz de destruir corpos de seres imortais, desde que esses sejam considerados “Malignos”. No entanto, tenha cuidado, pois, a essência imortal de um ser não é destruída, apenas o seu corpo físico.',
