    historia: 'Mirio é um Saiyajin refugiado, sua família era de classe baixa e não tinham atenção da força frieza, por isso, ninguém sentiu falta quando eles fugiram usando\numa Nave velha que ficava nos depósitos no reino, e que sorte, poucos anos depois, o Planeta foi destruído, a família se estabeleceu em um planeta que era supostamente inabitado e inóspito, mas a verdadeira vida do planeta ficava debaixo do planeta, que era oco, o planeta era chamado pelos seus habitantes de Forja Oca, lá, a natureza se misturava com as cidades bem habitadas e harmoniosas, seus habitantes os saradins são um povo cuja aparência parece com insetos robóticos, mas que suas faces parecem mais uma máscara plana.\nDe início, a família foi tratada como invasores saiyajins comuns, mas o contrário foi provado com o testemunho do Pai Nizinra men (Nissin Lamem) e com a notícia da destruição do Planeta Vegeta, com isso, eles lentamente ganharam seu lugar junto ao povo Saradin, sua cultura pacifica mas militar era algo que a família saiyajin se identificava, Mirio fez muitos amigos e aprendeu com seus novos irmãos a arte da forja e do manuseio de Espadas, crescer em um povo tão pacifico e altruísta criou um senso de dever e justiça no coração de Mirio, ele teve de lutar com eventuais Bandidos e bestas que viviam nos Abismos ou na superfície do planeta, porém, uma coisa que Mirio nunca fez, foi tirar a vida de alguém, porque sentia que matar era um ato imperdoável, com uma exceção, Frezza, Mirio Prometeu que um dia iria mata-lo mesmo que ele soubesse que provavelmente jamais iria cumprir, porque uma vez que entraram no planeta, não tinha como sair, porque a tecnologia do planeta não era avançada para criar naves intergalácticas, mas seu irmão\n\fCurponu Dus (Cup Noodles) e o líder de avanços tecnológicos do planeta conseguiram estudar a base da tecnologia da força frieza para criar tecnologia espacial, mas esse avanço custou um grande preço.\nQuando a nave foi consertada e mais naves com molde parecido foram confeccionadas, o Gps da nave original voltou a funcionar e o exército frezza foi tirar satisfação, um pelotão de soldados invadiram o planeta e começaram uma verdadeira GUERRA, Saradins e Soldados do Frezza sendo mortos por todo lado, Mirio foi uma das peças fundamentais para a luta, mesmo que não eliminasse nenhum inimigo, ele foi o que mais nocauteou soldados, junto com seu irmão que usava de Pistolas de Ki e seus amigos Saradianos Byzourrin (Besourin) e Kabuto que voavam com suas asas, o "time dos mocinhos" estava vencendo até que o verdadeiro problema apareceu, Dodoria, um problema que nem todo o planeta junto poderia combater, a partir desse momento, a batalha virou completamente, Mirio levou uma surra e foi jogado para o outro lado do planeta, nocauteado, já os familiares, amigos e o povo do planeta Saradin foram exterminados.\nQuando Mirio acordou, o planeta era só destroços, o "teto" do planete desmoronou e devastou a paisagem paradisíaca e utópica que vivia debaixo do planeta, não sobrou ninguém, com o pouco que sobrou, Mirio conseguiu se curar, e sobreviver, com uma marca em seu corpo e sua mente, os últimos dias no planeta foram gastos fazendo uma homenagem para o povo saradin, seus amigos e a família de mirio, no último dia, ele pegou a última nave que sobrou, a nave que sua família usou para fugir para esse planeta e voou para buscar força e aliados para exterminar toda a força Frezza.',
