    transformacoes: [],
    passivas: [],
    historia: 'Erik Ko’nuar\nTempo... Isso, para mim, é um assunto delicado. Em que ano estamos? Ou melhor, em que ano eu deveria estar... Há um tempo, eu vi esse objeto. Um brinco. Um brinco dos seres nomeados como “Deuses da Criação”, conhecidos no universo como Supremos Senhores Kaioh. Mas o que eu não sabia era que esses seres existem em cada aspecto individual da existência vida, morte e tempo. Andando na minha cidade natal, antes de ir para o trabalho, eu vi esse objeto no chão. Parecendo uma pedra, estava totalmente queimado. Após levá-lo para casa e limpá-lo rapidamente, percebi que aquilo era um brinco, e que parecia ser bem valioso. Pensei logo em vender. Mas antes, eu o coloquei na orelha e olhei para o relógio. Vi que eram umas 6h40 da manhã e que meu trabalho era só às 8h. Fiz uma conta rápida e percebi que ainda dava tempo de pegar o trem. Corri até a estação, peguei o trem e fui para o meu trabalho. Chegando à empresa, fui direto para o computador e comecei aquela manhã cansativa. Levantei-me, fui tomar um café e entrei no banheiro. Então, de repente, eu estava andando na rua de novo. Olhei para o lado e vi uma pedra meio queimada. Antes de ir para o trabalho, eu havia visto esse objeto no chão e levado para casa para limpá-lo. Rapidamente percebi que aquilo era um brinco, que parecia ser bem valioso. Pensei logo em vender. Então fui olhar o relógio e vi... espera. Ainda são 6h40? Eu jurei que já tinha feito mais... coisas?\n\fNaquele momento, percebi. Eu podia voltar no tempo.\nRevivi esse dia umas cem vezes antes de começar a notar as mudanças temporais. Meu corpo, no começo, não percebia essa distorção. Mas toda vez que eu olhava para o relógio, me dava conta do tempo que retrocedia. Usei isso, no começo, para entender meus “poderes” e fui atrás de respostas. Estudei muito e compreendi a existência do ki, e dos lutadores que pareciam deuses em combate. Afundei nesse mundo de ki e, quando percebi, eu conseguia ver o “tempo” como uma linha. E mais do que ver... eu podia mudá-la.\nQuando puxava essa linha, eu voltava no tempo. Aos poucos, aprendi a usar esses poderes em objetos. Jogava uma bola de papel no chão e conseguia retroceder apenas aquele objeto. E assim começou a minha jornada como guerreiro... o próximo terráqueo mais procurado da Galáxia do Norte pela Federação Galáctica. Bem, eu ainda tenho muita história para contar. Então você, que está lendo isso... já pensou em voltar? Em lutar contra os seus erros? Em se sentir livre dos seus arrependimentos? Eu te garanto... ess..\n— Hey! Achamos ele! PEGUEM-NO!!! Termino minha gravação aqui. Até mais.',
