        descricao: 'Domínio raro entre os habitantes dos Reinos Superiores, as Artes da Visão Distante permitem que o usuário projete sua consciência para observar eventos em tempo real em qualquer parte dos Reinos Inferiores. Aqueles que dominam essa técnica podem enxergar lugares, pessoas e até detectar distúrbios no fluxo de energia vital à grandes distâncias, sem serem notados. Usuários experientes conseguem usar a técnica para monitorar batalhas, investigar ameaças ou buscar conhecimento oculto. No entanto, é amplamente conhecido que alguns indivíduos — em especial certos Deuses menores e Anciãos entediados — abusam vergonhosamente dessa habilidade para espiar atividades triviais, como torneios de vôlei de praia femininos ou banhos em fontes termais (também femininos), alegando "interesse cultural".',
