    historia: 'Sendo uma ex Habitante do segundo reino demoníaco por motivo de\ndescontentamento com a situação de lá, Amai Kēki é uma Glind nascida de um fruto comum que ocasionalmente transita entre dimensões. Sendo encontrada maior parte no tempo no outro mundo, no inferno aonde ocorre o seu treinamento, e no paraíso onde possui uma casinha. De tempos em tempos ela começa a viajar pelas dimensões apenas para visita-los e para se atualizar sobre os acontecimentos que ocorreram no universo.\nSendo Possuidora de técnicas desenvolvidas ao longo dos anos de seu treinamento que envolvem ki e magia, sendo a última a suas favoritas, ela se tornou uma bruxa com uma força notável devido as suas habilidades. E depois de uma batalha contra um poderoso majin, e quase morrer. Amai Kēki após essa derrota decidiu que continuaria seu treino com um discípulo de coração justo para repassar seu conhecimento e para com isso conseguir formar alguém bastante poderoso e além aumentar a suas próprias habilidades, para quem sabe mudar o rumo das coisas ruins que acontecem no universo.',
