        nome: 'Conquista Absoluta',
        tipo: 'Passiva',
        texto: 'A cada batalha, Yama sente o mundo inteiro comprimido a um único ponto: o próximo oponente digno. Seu corpo reage ao conflito como se a luta fosse o único oxigênio que ele precisa. Quanto mais forte o adversário, mais vivo ele se sente — e mais sua aura roxo-clara se intensifica, como se o próprio universo estivesse sendo puxado para dentro de sua fúria crescente. Diante de inimigos poderosos, sua mente gélida se aquieta, mas seu poder desperta sem limites. A sensação é de inevitabilidade: Yama cresce junto do perigo. • Sempre que Yama sofrer dano de um inimigo com atributo maior que o dele (For, Dex, Poder, etc.), ele recebe +1 acúmulo de Conquista (máx. Igual a sua EP). • Cada acúmulo dá +03 de dano bônus em suas técnicas e +1 em testes de resistência. • Ao atingir o máximo acúmulos, Yama entra em Estado de Predação: Seus ataques ignoram 50% de mitigação. • Os acúmulos se perdem após 1 turno sem causar dano ao alvo que atributo maior que o seu.',
