        texto: 'Rakthar é um combatente de domínio total de energia bruta, misturando ataques Majin com manipulação gravitacional. Seu estilo é ritmado e imprevisível, alternando entre movimentos lentos e explosões de velocidade insana. Há algo de ritualístico em sua forma de lutar, como se cada confronto fosse uma performance macabra onde o adversário é simultaneamente espectador e vítima e onde o sangue derramado serve como aplauso. Ao início de seu turno de ação, seu coração começa a bater forte, aumentando o compasso a cada rodada. Dessa forma, ativando uma variação dessa passiva a cada rodada que se passa seguindo a ordem, reiniciando na oitava rodada, em um ciclo infinito até a batalha encerrar.\n\nRakthar é um combatente de domínio total de energia bruta, misturando ataques Majin com manipulação gravitacional. Seu estilo é ritmado e imprevisível, alternando entre movimentos lentos e explosões de velocidade insana. Há algo de ritualístico em sua forma de lutar, como se cada confronto fosse uma performance macabra onde o adversário é simultaneamente espectador e vítima e onde o sangue derramado serve como aplauso. Ao início de seu turno de ação, seu coração começa a bater forte, aumentando o compasso a cada rodada. Dessa forma, ativando uma variação dessa passiva a cada rodada que se passa seguindo a ordem, reiniciando na oitava rodada, em um ciclo infinito até a batalha encerrar. ✓ Crimson Pulse — O Primeiro Batimento: Rakthar condensa seu Ki em forma líquida e o dispara como uma onda pulsante que desintegra matéria e absorve energia vital. A próxima técnica que utilizar, irá ter de forma passiva, os rótulos “Alcance em Cone de X metros”, Tipo de Dano “Desintegrante”, Tipo de Dano “Drenagem”. Onde para ativar o efeito dos rótulos basta acertar o inimigo ao invés de dobrar o limite necessário para causar um estágio de dano máximo. ✓ Crimson Rapture — O Segundo Batimento: Técnica corpo a corpo onde Rakthar transforma seus membros em lâminas líquidas vibrantes, desferindo golpes rítmicos que atravessam carne e energia. Cada impacto produz uma pulsação sonora profunda, como uma batida cardíaca amplificada — a sinfonia do colapso. Até o final da rodada do Segundo Batimento, todos seus golpes físicos tem o rótulo “Tipo de Dano Cortante”, caso os golpes já tenham este rótulo, eles são ativados duas vezes. ✓ Selo Invertido — O Terceiro Batimento: O símbolo Majin em sua testa se distorce, emitindo uma onda psíquica que desestabiliza o foco e a coordenação do adversário. Todos os alvos a frente do alvo em um Cone de X metros, devem realizar um Teste de Constituição vs CD do Usuário, onde em falha gastam do dobro de PK’s até o início do próximo turno de ação do Majin. ✓ Graviton Veil — O Quarto Batimento: O Majin cria um campo gravitacional denso ao redor do corpo, curvando projéteis e ataques energéticos — uma defesa viva. Até o início do seu próximo turno, não pode ser atingido por técnicas ofensivas com o rótulo de Projétil, de forma absoluta. ✓ Graviton Maelstrom — O Quinto Batimento: Girando o corpo em um redemoinho denso de energia e sangue líquido, Rakthar cria um vórtice gravitacional devastador, com uma área de raio de X metros a partir do Majin. Os golpes formam uma espiral viva que deforma o espaço ao redor e arremessa inimigos próximos — uma dança infernal de gravidade e carnificina. Todos na área estão sob o efeito do rótulo “Dano Gravitacional”, até o fim do próximo turno do Majin, sem direito a resistência. ✓ Majin Overdrive — O Sexto Batimento: Um grito silencioso que colapsa a energia local, drenando o ki de todos os seres próximos e fundindo com o seu próprio poder. Todos os alvos a frente do alvo em um Cone de X metros, devem realizar um Teste de Constituição vs CD do Usuário, caso falhem perdem metade de seus PK’s atuais, e estes são convertidos em Dano Bônus para próxima técnica ofensiva que o usuário desferir. ✓ Ritual da Ruína — O Sétimo Batimento: A Técnica Final. O sangue de Rakthar escapa do corpo e o envolve em um manto líquido, assumindo uma forma viva. Nesse estado, cada golpe acerta o corpo e o espírito ao mesmo tempo. Todo dano causado pelo Majin até o final de seu próximo turno de ação, será também aplicado nos PK’s do alvo, sem direito a teste de resistência.\n\n- 1: Crimson Pulse: O Primeiro Batimento: Rakthar condensa seu Ki em forma líquida e o dispara como uma onda pulsante que desintegra matéria e absorve energia vital. A próxima técnica que utilizar, irá ter de forma passiva, os rótulos “Alcance em Cone de X metros”, Tipo de Dano “Desintegrante”, Tipo de Dano “Drenagem”. Onde para ativar o efeito dos rótulos basta acertar o inimigo ao invés de dobrar o limite necessário para causar um estágio de dano máximo.\n- 2: Crimson Rapture: O Segundo Batimento: Técnica corpo a corpo onde Rakthar transforma seus membros em lâminas líquidas vibrantes, desferindo golpes rítmicos que atravessam carne e energia. Cada impacto produz uma pulsação sonora profunda, como uma batida cardíaca amplificada — a sinfonia do colapso. Até o final da rodada do Segundo Batimento, todos seus golpes físicos tem o rótulo “Tipo de Dano Cortante”, caso os golpes já tenham este rótulo, eles são ativados duas vezes.\n- 3: Selo Invertido: O Terceiro Batimento: O símbolo Majin em sua testa se distorce, emitindo uma onda psíquica que desestabiliza o foco e a coordenação do adversário. Todos os alvos a frente do alvo em um Cone de X metros, devem realizar um Teste de Constituição vs CD do Usuário, onde em falha gastam do dobro de PK’s até o início do próximo turno de ação do Majin.\n- 4: Graviton Veil: O Quarto Batimento: O Majin cria um campo gravitacional denso ao redor do corpo, curvando projéteis e ataques energéticos — uma defesa viva. Até o início do seu próximo turno, não pode ser atingido por técnicas ofensivas com o rótulo de Projétil, de forma absoluta.\n- 5: Graviton Maelstrom: O Quinto Batimento: Girando o corpo em um redemoinho denso de energia e sangue líquido, Rakthar cria um vórtice gravitacional devastador, com uma área de raio de X metros a partir do Majin. Os golpes formam uma espiral viva que deforma o espaço ao redor e arremessa inimigos próximos — uma dança infernal de gravidade e carnificina. Todos na área estão sob o efeito do rótulo “Dano Gravitacional”, até o fim do próximo turno do Majin, sem direito a resistência.\n- 6: Majin Overdrive: O Sexto Batimento: Um grito silencioso que colapsa a energia local, drenando o ki de todos os seres próximos e fundindo com o seu próprio poder. Todos os alvos a frente do alvo em um Cone de X metros, devem realizar um Teste de Constituição vs CD do Usuário, caso falhem perdem metade de seus PK’s atuais, e estes são convertidos em Dano Bônus para próxima técnica ofensiva que o usuário desferir.\n- 7: Ritual da Ruína: O Sétimo Batimento: A Técnica Final. O sangue de Rakthar escapa do corpo e o envolve em um manto líquido, assumindo uma forma viva. Nesse estado, cada golpe acerta o corpo e o espírito ao mesmo tempo. Todo dano causado pelo Majin até o final de seu próximo turno de ação, será também aplicado nos PK’s do alvo, sem direito a teste de resistência.',
