    historia: 'Nascido da falha de um experimento de purificação do Ki Majin, o recipiente que o continha se desfez e o que restou foi uma poça de sangue viva. Desse fracasso, emergiu Rakthar, uma anomalia carmesim, a personificação da negação da pureza, um líquido pulsante que se recusava a morrer.\nO responsável foi um mago esquecido do Sétimo Universo, trabalhando em seu laboratório isolado no planeta Gorgul Prime. Sua ambição era criar um Majin capaz de processar emoções humanas sem sucumbir a elas. O resultado, ironicamente, foi uma criatura que não apenas absorve emoções - ele as domina completamente.\nPor eras incontáveis, Rakthar perambulou entre mundos devastados pela guerra. Cada conflito presenciado, cada gota de ódio e desespero absorvida tornava seu corpo mais denso, sua consciência mais aguçada. Seu corpo - uma massa de sangue vivo entrelaçado com energia vital condensada - começou a distorcer a própria realidade ao seu redor. A gravidade se curva em sua presença.\nHoje, ele é um andarilho entre realidades como um eco vermelho que não sabe se busca redenção pela vida que nunca teve ou a paz que só a aniquilação total pode trazer.\nDiz-se que, quando ele fala, o som vibra em frequências que quebram a vontade de quem o escuta.',
